// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface DonorOut {
  donor_id: number;
  /** For the donor's life (PBTA Standards ch.2 S.1.1.2) */
  donor_number: string;
  full_name: string;
  sex: "Male" | "Female";
  date_of_birth: string;
  age_years: number;
  id_kind: "CNIC" | "Passport" | "ProofOfRegistration" | "Other";
  id_number: string;
  phone: string | null;
  email: string | null;
  address: string | null;
  registered_by: number;
  registered_at: string;
  /** A deferral is in force today: not accepted */
  deferred_now: boolean;
  permanently_deferred: boolean;
  last_collected_at: string | null;
  donations_collected: number | null;
  /** From the latest cleared donation */
  abo: "A" | "B" | "AB" | "O" | null;
  rh: "Positive" | "Negative" | null;
  /** The first day the interval and any temporary deferral allow (meaningless when permanently_deferred) */
  may_donate_from: string | null;
  row_version: number;
}

