export interface DonorDeferralOut {
  deferral_id: number;
  donor_id: number;
  donation_id: number | null;
  donation_number: string | null;
  kind: "Temporary" | "Permanent";
  reason: string;
  deferred_from: string;
  /** Temporary: the last day; Permanent: none */
  deferred_until: string | null;
  decided_by: number;
  decided_stamp: AuthorStampOut;
  decided_at: string;
  /** When the donor was told why (the Act s.10(2)(e)) */
  communicated_at: string | null;
  communicated_by: number | null;
  communication: "InPerson" | "Phone" | "Letter" | null;
  counselled: boolean;
  referred_to: string | null;
  /** Entered in error: revoked, kept on the record */
  revoked_at: string | null;
  revoked_by: number | null;
  revoke_reason: string | null;
  in_force: boolean;
  row_version: number;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface DonorDonationSummaryOut {
  donation_id: number;
  donation_number: string;
  attended_at: string;
  donation_kind: "Voluntary" | "Replacement" | "Autologous";
  venue: "BloodCenter" | "Camp";
  status: "Accepted" | "Deferred" | "Collected" | "Unsuccessful" | "Cleared" | "Reactive" | "Rejected";
  hb_g_dl: number;
  volume_ml: number | null;
  abo: "A" | "B" | "AB" | "O" | null;
  rh: "Positive" | "Negative" | null;
}

/** The donor's attendance and the doctor's assessment (Std ch.2 S.2.3): the history questionnaire reviewed, the weight, the haemoglobin, the vital signs, and the decision. Accepted needs the written consent signed and the donor's declaration that they are not paid (the Act s.2(k)); Deferred needs the deferral. */
export interface DonationIn {
  donor_id: number;
  donation_kind: "Voluntary" | "Replacement" | "Autologous";
  /** Replacement or autologous: the patient */
  for_patient_id?: number | null;
  venue: "BloodCenter" | "Camp";
  /** A camp: where */
  venue_note?: string | null;
  /** The center's donor questionnaire answered and reviewed */
  history_completed: boolean;
  history_note?: string | null;
  weight_kg: number | string;
  hb_g_dl: number | string;
  hb_method: "CopperSulphate" | "Photometer" | "Haematocrit" | "Analyser";
  pulse?: number | null;
  bp_systolic?: number | null;
  bp_diastolic?: number | null;
  temperature_c?: number | string | null;
  outcome: "Accepted" | "Deferred";
  /** The written consent signed before donation (Std ch.2 S.1.2.4); never ticked in advance */
  consent_signed?: boolean;
  consent_language?: string | null;
  /** The donor declares no payment or compensation (never ticked in advance) */
  unpaid_declared?: boolean;
  /** Deferred: the deferral (kind, reason, period, how told) */
  deferral?: DonorDeferralIn | null;
}

/** The doctor's deferral: Temporary until a last day, or Permanent, with the reason (the Authority's criteria; the lists in the PBTA SOP manual are guidance for the doctor). `told` when the donor was told at once. */
export interface DonorDeferralIn {
  kind: "Temporary" | "Permanent";
  reason: string;
  /** Default: today */
  deferred_from?: string | null;
  /** Temporary: the last day of the deferral; Permanent: none */
  deferred_until?: string | null;
  /** The donation that showed it (a reactive screen), if any */
  donation_id?: number | null;
  told?: DonorTellIn | null;
}

/** How the donor was told why (the Act s.10(2)(e)), by the doctor recording it. */
export interface DonorTellIn {
  communicated_at: string;
  communication: "InPerson" | "Phone" | "Letter";
  counselled?: boolean;
  /** The diagnostic laboratory a reactive donor is referred to for confirmation (Std ch.4 S.2.1.4) */
  referred_to?: string | null;
}

